const P4 = "/tspan></text>";
const P5 = "</svg>\n";

const COL_SINGLE_X = [11.819459, 18.602053, 25.384647, 32.167244, 38.949841, 45.732433, 52.51503];
const COL_TENS_X   = [9.5579319, 16.340527, 23.123121, 29.905714, 36.688313, 43.470909, 50.253502];
const COL_UNITS_X  = [11.819459, 18.602053, 25.384647, 32.167244, 38.648037, 45.732433, 52.51503];
const ROW_Y        = [32.950909, 38.424427, 43.897945, 49.371464, 54.844982, 60.318500];
const HEART_RAW_CX = 39.0818;
const HEART_RAW_CY = 47.9111;
const HEART_RAW_W  = 5.0907;
const HEART_RAW_H  = 3.9013;
const FONT_SIZE    = 4.06638;
const CAP_RATIO    = 0.716;
const STYLE_NUM    = 'font-size:4.06638px;font-family:Arial;-inkscape-font-specification:Arial;stroke-width:0.169433';
const MONTHS_BY_LANG = {
  hu: ['Január','Február','Március','Április','Május','Június','Július','Augusztus','Szeptember','Október','November','December'],
  de: ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'],
};
const NAMES_X          = 9.6479845;
const NAMES_RIGHT      = 51.8637;
const NAMES_BASE_FS    = 8.06015;
const NAMES_AVG_RATIO  = 0.45;

export function buildCalendar(year, month) {
  let firstDow = new Date(year, month-1, 1).getDay();
  firstDow = firstDow === 0 ? 6 : firstDow - 1;
  const totalDays = new Date(year, month, 0).getDate();
  const weeks = []; let week = [];
  for (let i = 0; i < firstDow; i++) week.push(null);
  for (let d = 1; d <= totalDays; d++) {
    week.push(d);
    if (week.length === 7) { weeks.push(week); week = []; }
  }
  if (week.length > 0) { while (week.length < 7) week.push(null); weeks.push(week); }
  return weeks;
}

function rowYPositions(calendarLength) {
  // Normal esetben (max 5 het) a fix ROW_Y ertekeket hasznaljuk. Ha egy
  // honapnak 6 hete van (pl. 2026 augusztus), a 6. sor nem kaphat sajat,
  // ROW_Y[5]-nek megfelelo helyet, mert az mar atlogna a nevek feletti FIX
  // pozicioju elvalaszto csikba es a keretbe (path138-1-2) - ezek a
  // fizikai kartya kimozdithatatlan elemei, nem tolhatok el. Ehelyett a 6
  // sort besuritjuk ugyanabba a fuggoleges savba, amit eredetileg az 5 sor
  // foglalt el (ROW_Y[0]-tol ROW_Y[4]-ig), igy a 6. sor pontosan ott vegzodik,
  // ahol korabban az 5. sor - a csik/nevek/keret pozicioja valtozatlan marad.
  if (calendarLength < 6) return ROW_Y;
  const top = ROW_Y[0], bottom = ROW_Y[4];
  const step = (bottom - top) / 5;
  return [0, 1, 2, 3, 4, 5].map(r => top + r * step);
}

function heartTransform(heartRow, heartCol, belowDay, rowY) {
  const baseline = rowY[heartRow];
  const capH  = FONT_SIZE * CAP_RATIO;
  const rowH  = rowY[1] - rowY[0];
  const colW  = COL_TENS_X[1] - COL_TENS_X[0];
  const scale = Math.min(rowH * 0.9 / HEART_RAW_H, colW * 0.85 / HEART_RAW_W);
  const targetCX = (belowDay !== null && belowDay >= 10) ? COL_UNITS_X[heartCol] : COL_SINGLE_X[heartCol];
  const targetCY = baseline - capH / 2;
  return `transform="translate(${targetCX.toFixed(4)},${targetCY.toFixed(4)}) scale(${scale.toFixed(4)}) translate(${(-HEART_RAW_CX).toFixed(4)},${(-HEART_RAW_CY).toFixed(4)})"`;
}

function namesFontSize(name1, name2) {
  const full = name1 + ' & ' + name2;
  const estW = full.length * NAMES_BASE_FS * NAMES_AVG_RATIO;
  const maxW = NAMES_RIGHT - NAMES_X;
  return estW > maxW ? NAMES_BASE_FS * (maxW / estW) : NAMES_BASE_FS;
}

export function generateSVG(name1, name2, year, month, day, lang) {
  const calendar = buildCalendar(year, month);
  let heartRow = -1, heartCol = -1;
  for (let r = 0; r < calendar.length; r++) {
    const ci = calendar[r].indexOf(day);
    if (ci !== -1) { heartRow = r; heartCol = ci; break; }
  }
  const belowDay = (heartRow+1 < calendar.length) ? calendar[heartRow+1][heartCol] : null;
  const rowY = rowYPositions(calendar.length);
  const ht = heartTransform(heartRow, heartCol, belowDay, rowY);

  let numElems = ''; let idc = 200;
  for (let r = 0; r < calendar.length; r++) {
    const y = rowY[r];
    for (let c = 0; c < 7; c++) {
      const d = calendar[r][c];
      if (d === null) continue;
      if (r === heartRow && c === heartCol) continue;
      if (d < 10) {
        numElems += `\n  <text\n     style="${STYLE_NUM}"\n     x="${COL_SINGLE_X[c]}"\n     y="${y}"\n     id="t${idc++}">${d}</text>`;
      } else {
        const t = Math.floor(d/10), u = d%10;
        numElems += `\n  <text\n     style="${STYLE_NUM}"\n     x="${COL_TENS_X[c]}"\n     y="${y}"\n     id="t${idc++}">${t}</text>`;
        numElems += `\n  <text\n     style="${STYLE_NUM}"\n     x="${COL_UNITS_X[c]}"\n     y="${y}"\n     id="t${idc++}">${u}</text>`;
      }
    }
  }

  const fs  = namesFontSize(name1, name2);
  const maxW = (NAMES_RIGHT - NAMES_X).toFixed(4);
  const p3  = P3.replace(/font-size:8\.06015px/g, `font-size:${fs.toFixed(5)}px`);
  const months = MONTHS_BY_LANG[lang] || MONTHS_BY_LANG.hu;
  const monthLabel = `>${months[month-1]} ${year}<`;
  const namesStr   = ` textLength="${maxW}" lengthAdjust="spacingAndGlyphs">${name1} &amp; ${name2}<`;

  let svg = P1 + monthLabel + P2 + ht + p3 + namesStr + P4 + numElems + '\n' + P5;

  // A honap/ev felirat eredeti sablonja egy FIX, bal-igazitott x-koordinatan
  // allt, ami csak a "Szeptember"-nel (az eredeti tervezes soran hasznalt
  // pelda-honapnal) nezett ki kozepre igazitottnak - minden mas honapnevre
  // (pl. "Augusztus") a szoveg eltero szelessege miatt LATHATOAN elcsuszott a
  // fekete sav kozepehez kepest. Kozepre igazitas: a fekete sav (rect927-5-7)
  // x=5.9813447, width=52.309971 -> kozepe = 32.136331.
  svg = svg.replace(/x="17\.559452"/g, 'x="32.136331" text-anchor="middle"');

  return svg;
}


const WOOD_TEXTURE_B64 = "";

// A pontos generateSVG() kimenetet UTOLAGOSAN alakitja at latvanytervve:
// 1) a kulso sziluett (lezervago, piros korvonal a forrasfajlban) fa-mintaval
//    toltodik ki egy SVG <pattern>-en keresztul, a korvonala alig lathato
//    marad (ez csak a lezervago gepnek szolo technikai jelzes volt eredetileg),
// 2) a naptar-szamok korul futo diszkeret (path138-1-2, eredetileg kek
//    korvonal = hajtas/score jelzes a lezerfajlban) sotetebb szurkere valtozik,
//    mert ez a latvanytervben tenylegesen latszo diszito keret, nem technikai
//    jelzes.
export function generateMockupSVG(name1, name2, year, month, day, lang) {
  let svg = generateSVG(name1, name2, year, month, day, lang);

  const defs =
    '<defs><pattern id="woodGrain" patternUnits="userSpaceOnUse" ' +
    'x="0" y="0" width="64.272954" height="76.16226">' +
    '<image href="data:image/jpeg;base64,' + WOOD_TEXTURE_B64 + '" ' +
    'x="0" y="0" width="64.272954" height="76.16226" ' +
    'preserveAspectRatio="xMidYMid slice" /></pattern></defs>';
  svg = svg.replace("<sodipodi:namedview", defs + "<sodipodi:namedview");

  svg = svg.replace(
    "fill:none;stroke:#ff0000;stroke-width:0.176389;stroke-opacity:1",
    "fill:url(#woodGrain);stroke:#00000022;stroke-width:0.176389;stroke-opacity:1"
  );
  svg = svg.replace(
    "fill:none;fill-opacity:1;stroke:#0000ff;stroke-width:0.176389;stroke-opacity:1",
    "fill:none;fill-opacity:1;stroke:#000000aa;stroke-width:0.352778;stroke-opacity:1"
  );

  return svg;
}
